      "to": "Monthly Inventory Record",
      "description": "Equipment reservations contribute data to monthly inventory records"
    },
    {
      "from": "Rental Manager",
      "to": "Rental Agreement",
      "description": "Rental Manager creates and updates rental agreements"
    },
    {
      "from": "Rental Agreement",
      "to": "Customer",
      "description": "Rental agreement binds customer to rental terms"
    },
    {
      "from": "Customer",
      "to": "Payment",
      "description": "Customer makes payments for rental services"
    },
    {
      "from": "Customer",
      "to": "Customer Feedback",
      "description": "Customer provides feedback about rental experience"
    },
    {
      "from": "Rental Manager",
      "to": "Customer Feedback",
      "description": "Rental Manager reviews and acts on customer feedback"
    },
    {
      "from": "Rental Manager",
      "to": "Monthly Revenue Report",
      "description": "Rental Manager analyzes monthly revenue reports"
    },
    {
      "from": "Rental Manager",
      "to": "Equipment Order",
      "description": "Rental Manager places new equipment orders"
    },
    {
      "from": "Equipment Distributor",
      "to": "Equipment Order",
      "description": "Equipment distributor fulfills equipment orders"
    },
    {
      "from": "Maintenance Technician",
      "to": "Maintenance Inspection",
      "description": "Maintenance technician performs equipment inspections"
    },
    {
      "from": "Maintenance Technician",
      "to": "Malfunction Report",
      "description": "Maintenance technician creates malfunction reports"
    },
    {
      "from": "Malfunction Report",
      "to": "Rental Manager",
      "description": "Malfunction report alerts rental manager to equipment issues"
    },
    {
      "from": "Maintenance Technician",
      "to": "Maintenance Log",
      "description": "Maintenance technician updates maintenance logs"
    },
    {
      "from": "Delivery Driver",
      "to": "Equipment Delivery",
      "description": "Delivery driver handles equipment deliveries"
    },
    {
      "from": "Accountant",
      "to": "Invoice",
      "description": "Accountant generates and manages invoices"
    },
    {
      "from": "Accountant",
      "to": "Invoice Reminder",
      "description": "Accountant sends invoice reminders for overdue payments"
    },
    {
      "from": "Invoice Reminder",
      "to": "Customer",
      "description": "Invoice reminder notifies customer of overdue payment"
    },
    {
      "from": "Accountant",
      "to": "Payment",
      "description": "Accountant records and processes customer payments"
    },
    {
      "from": "Payment",
      "to": "Invoice",
      "description": "Payment settles outstanding invoice amounts"
    }
  ]
}
```
